answer_code:
class Solution {
    static int digitCount(int n) {
        if (n == 0) {
            return 1;
        }
        int rest = Math.abs(n);
        int count = 0;
        while (rest > 0) {
            count++;
            rest /= 10;
        }
        return count;
    }
}

