class Solution {
    static int max(int[] a) {
        if (a.length == 0) {
            throw new IllegalArgumentException("配列が空です");
        }
        int best = a[0];
        for (int i = 1; i < a.length; i++) {
            if (a[i] > best) {
                best = a[i];
            }
        }
        return best;
    }
}

