class Solution {
    static int[] rowSums(int[][] grid) {
        int[] sums = new int[grid.length];
        for (int i = 0; i < grid.length; i++) {
            int total = 0;
            for (int v : grid[i]) {
                total += v;
            }
            sums[i] = total;
        }
        return sums;
    }
}

