import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

class Solution {
    static List<String> keysInOrder(Map<String, Integer> src) {
        return new ArrayList<>(new TreeMap<>(src).keySet());
    }

    static String joinInKeyOrder(Map<String, Integer> src) {
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<String, Integer> entry : new TreeMap<>(src).entrySet()) {
            if (sb.length() > 0) {
                sb.append(",");
            }
            sb.append(entry.getKey()).append("=").append(entry.getValue());
        }
        return sb.toString();
    }
}

