import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;

class Solution {
    static List<String> serve(List<String> arrivals, int n) {
        Queue<String> queue = new ArrayDeque<>();
        for (String person : arrivals) {
            queue.offer(person);
        }
        List<String> served = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String next = queue.poll();
            if (next == null) {
                break;
            }
            served.add(next);
        }
        return served;
    }

    static String firstOrNull(List<String> items) {
        Queue<String> queue = new ArrayDeque<>(items);
        return queue.peek();
    }
}

