        this.radius = radius;
    }

    public double area() {
        return radius * radius * Math.PI;
    }

    public String name() {
        return "円";
    }
}

class Rect implements Shape {
    private final double width;
    private final double height;

    Rect(double width, double height) {
        this.width = width;
        this.height = height;
    }

    public double area() {
        return width * height;
    }

    public String name() {
        return "長方形";
    }
}

class Solution {
    // 図形の合計面積を返す
    static double totalArea(Shape[] shapes) {
        double sum = 0.0;
        for (Shape s : shapes) {
            sum += s.area();
        }
        return sum;
    }
}

