import java.util.ArrayList;
import java.util.List;

class Solution {
    // 文字数の昇順に並べ替えた新しいリストを返す
    static List<String> sortedByLength(List<String> words) {
        List<String> copy = new ArrayList<>(words);
        copy.sort((a, b) -> a.length() - b.length());
        return copy;
    }

    // 数値の降順に並べ替えた新しいリストを返す
    static List<Integer> sortedDesc(List<Integer> numbers) {
        List<Integer> copy = new ArrayList<>(numbers);
        copy.sort((a, b) -> b - a);
        return copy;
    }
}

