    // keep.test(n) が true の要素だけを集めた新しいリストを返す
    static List<Integer> filter(List<Integer> numbers, Predicate<Integer> keep) {
        List<Integer> result = new ArrayList<>();
        for (Integer n : numbers) {
            if (keep.test(n)) {
                result.add(n);
            }
        }
        return result;
    }

    // 条件に合う要素の個数を返す
    static int countMatching(List<String> words, Predicate<String> condition) {
        int count = 0;
        for (String w : words) {
            if (condition.test(w)) {
                count++;
            }
        }
        return count;
    }
}

