import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.Supplier;

class Solution {
    // supplier から n 個の値を作り、リストにして返す
    static List<String> repeat(int n, Supplier<String> supplier) {
        List<String> result = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            result.add(supplier.get());
        }
        return result;
    }

    // items の各要素を consumer に渡す
    static void forEach(List<String> items, Consumer<String> consumer) {
        for (String item : items) {
            consumer.accept(item);
        }
    }
}

