import java.util.Optional;

class Solution {
    // 空文字でなければ値を包んだ Optional、空文字なら空の Optional を返す
    static Optional<String> nonEmpty(String s) {
        if (s.isEmpty()) {
            return Optional.empty();
        }
        return Optional.of(s);
    }

    // 値があればその文字数、無ければ -1 を返す
    static int lengthOrMinusOne(Optional<String> value) {
        if (value.isPresent()) {
            return value.get().length();
        }
        return -1;
    }
}

