class Solution {
    static long distance(int x1, int y1, int x2, int y2) {
        double dx = x2 - x1;
        double dy = y2 - y1;
        return Math.round(Math.sqrt(Math.pow(dx, 2) + Math.pow(dy, 2)));
    }

    static int absDiff(int a, int b) {
        return Math.abs(a - b);
    }
}

