import java.util.Objects;

class Solution {
    static class User {
        final String name;
        final Integer age;

        User(String name, Integer age) {
            this.name = name;
            this.age = age;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) {
                return true;
            }
            if (!(o instanceof User)) {
                return false;
            }
            User other = (User) o;
            return Objects.equals(name, other.name) && Objects.equals(age, other.age);
        }

        @Override
        public int hashCode() {
            return Objects.hash(name, age);
        }
    }
}
